local band = bit and bit.band or bit32 and bit32.band or function(a, b)
  local r, p = 0, 1
  while a > 0 and b > 0 do
    if a % 2 == 1 and b % 2 == 1 then r = r + p end
    a, b, p = math.floor(a / 2), math.floor(b / 2), p * 2
  end
  return r
end
function MA.Caps(displayId) local m = MA.displays[displayId] return m and MA.models[m] or nil end
function MA.Has(displayId, cap) local c = MA.Caps(displayId) return c ~= nil and band(c, cap) == cap end
function MA.Works(displayId) return MA.Has(displayId, MA.ALL) end
return MA
